/**
 * Just enough of the `vscode` module for patcher.js to be loaded and run outside
 * the editor. It is the one file that writes to somebody else's disk, and until
 * this stub existed it was also the only file with no test - which is how a build
 * that could not even load got as far as being handed over.
 *
 * It has since grown a `window`, for the one other thing worth checking without a
 * running editor: whether a person is asked about a fix they turned off, and how
 * often. "How often" is the whole question there, and it cannot be answered by
 * reading the code twice.
 */
let fakeExtensionPath = null;
const shown = [];
let answer = undefined;

module.exports = {
  __setClaudeCode(p) { fakeExtensionPath = p; },
  __shown: shown,
  __reset() { shown.length = 0; answer = undefined; },
  __answerWith(choice) { answer = choice; },
  extensions: {
    getExtension(id) {
      if (id !== "anthropic.claude-code" || !fakeExtensionPath) return undefined;
      return { extensionPath: fakeExtensionPath, packageJSON: { version: "2.1.247" } };
    }
  },
  window: {
    showInformationMessage(message, ...items) {
      shown.push({ message, items });
      return Promise.resolve(answer);
    }
  }
};
